<?php
if (!defined('ABSPATH')) exit;
/** Optional, administrator-driven region registry. No public requests or cron hooks. */
final class SDP_Region {
    const SCHEMA='1';
    const HEADER=['kode','kode_induk','jenis','nama'];
    const LEVELS=['provinsi'=>1,'kabupaten'=>2,'kota'=>2,'kecamatan'=>3,'desa'=>4,'kelurahan'=>4];
    const FIELDS=['provinsi','kabupaten','kecamatan','desa'];
    public static function boot(){add_action('admin_menu',[__CLASS__,'menu'],80);add_action('admin_post_sdp83_region',[__CLASS__,'action']);if(defined('WP_CLI')&&WP_CLI)WP_CLI::add_command('sdp regions',[__CLASS__,'cli'],['synopsis'=>'<file> --system=<system> --edition=<edition> --source=<source> --authorized=1']);}
    public static function table(){global $wpdb;return $wpdb->prefix.'sdp_regions';}
    public static function limits(){return ['rows'=>SDP_Resource::cap(1000,200),'bytes'=>SDP_Resource::cap(5242880,2097152)];}
    public static function ready(){return get_option('sdp83_region_schema')===self::SCHEMA;}
    public static function install(){global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$t=self::table();$c=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $t (
        `system` varchar(12) NOT NULL,
        edition varchar(32) NOT NULL,
        code varchar(20) NOT NULL,
        parent varchar(20) NOT NULL DEFAULT '',
        level tinyint unsigned NOT NULL,
        kind varchar(12) NOT NULL,
        name varchar(120) NOT NULL,
        name_key char(64) NOT NULL,
        source varchar(191) NOT NULL,
        PRIMARY KEY  (`system`,edition,code),
        KEY hierarchy (`system`,edition,parent,level,name_key)
    ) $c;");$found=$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($t)));if($found!==$t||$wpdb->last_error)return new WP_Error('schema','Tabel master wilayah gagal dibuat.');update_option('sdp83_region_schema',self::SCHEMA,false);return true;}
    public static function scope($system,$edition){if(!in_array($system,['kemendagri','bps'],true)||!preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]{0,31}$/D',$edition))return new WP_Error('scope','Sistem atau edisi tidak valid.');return ['system'=>$system,'edition'=>$edition];}
    public static function code($system,$code,$level){$patterns=$system==='kemendagri'?['\d{2}','\d{2}\.\d{2}','\d{2}\.\d{2}\.\d{2}','\d{2}\.\d{2}\.\d{2}\.\d{4}']:['\d{2}','\d{4}','\d{7}','\d{10}'];return isset($patterns[$level-1])&&preg_match('/^'.$patterns[$level-1].'$/D',$code)===1;}
    public static function parent($system,$code,$level){if($level===1)return '';return $system==='kemendagri'?substr($code,0,strrpos($code,'.')):substr($code,0,[2,4,7][$level-2]);}
    public static function name_parts($name,$level){$name=trim(preg_replace('/\s+/u',' ',trim($name))??'');$name=function_exists('mb_strtolower')?mb_strtolower($name,'UTF-8'):strtolower($name);$kind='';$prefix=[1=>['provinsi'=>'provinsi','prov'=>'provinsi'],2=>['kabupaten'=>'kabupaten','kab'=>'kabupaten','kota'=>'kota'],3=>['kecamatan'=>'kecamatan','kec'=>'kecamatan'],4=>['kelurahan'=>'kelurahan','kel'=>'kelurahan','desa'=>'desa']][$level]??[];if(preg_match('/^([a-z]+)\.?\s+(.+)$/u',$name,$m)&&isset($prefix[$m[1]])){$kind=$prefix[$m[1]];$name=$m[2];}return [$name,$kind];}
    public static function row($scope,$raw,$source){$kind=strtolower(trim($raw['jenis']??''));$level=self::LEVELS[$kind]??0;$code=trim($raw['kode']??'');$parent=trim($raw['kode_induk']??'');$name=trim($raw['nama']??'');if(!$level||!self::code($scope['system'],$code,$level)||$parent!==self::parent($scope['system'],$code,$level))return new WP_Error('code','Kode, induk, atau jenis wilayah tidak sesuai hierarki.');if(strlen($name)>120||!preg_match('/^[\p{L}\p{N}][\p{L}\p{N}\p{M} .\-\x{2019}\x{0027}()\/]*$/uD',$name))return new WP_Error('name','Nama wilayah kosong atau berisi karakter tidak didukung.');[$key,$prefix]=self::name_parts($name,$level);if($key===''||($prefix!==''&&$prefix!==$kind))return new WP_Error('name','Jenis wilayah bertentangan dengan nama.');if($level===2){if($prefix!=='')$name=preg_replace('/^[a-z]+\.?\s+/i','',$name,1);$name=($kind==='kota'?'Kota ':'Kabupaten ').$name;}if(strlen($name)>120)return new WP_Error('name','Nama kanonik terlalu panjang.');return $scope+['code'=>$code,'parent'=>$parent,'level'=>$level,'kind'=>$kind,'name'=>$name,'name_key'=>hash('sha256',$key),'source'=>$source];}
    public static function get($scope,$code){global $wpdb;$t=self::table();$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE `system`=%s AND edition=%s AND code=%s",$scope['system'],$scope['edition'],$code),ARRAY_A);return $wpdb->last_error?new WP_Error('database','Gagal membaca master wilayah.'):$r;}
    public static function lookup($scope,$parent,$level,$name){global $wpdb;$t=self::table();[$key,$kind]=self::name_parts($name,$level);if($key==='')return new WP_Error('missing','Nama wilayah kosong.');$args=[$scope['system'],$scope['edition'],$parent,$level,hash('sha256',$key)];$where='';if($kind!==''){$where=' AND kind=%s';$args[]=$kind;}$r=$wpdb->get_results($wpdb->prepare("SELECT code,parent,level,kind,name FROM $t WHERE `system`=%s AND edition=%s AND parent=%s AND level=%d AND name_key=%s$where LIMIT 2",...$args),ARRAY_A);if($wpdb->last_error||!is_array($r))return new WP_Error('database','Gagal mencari wilayah.');if(count($r)!==1)return new WP_Error(count($r)?'ambiguous':'missing',count($r)?'Nama wilayah ambigu; gunakan jenis kabupaten/kota atau desa/kelurahan.':'Wilayah tidak ditemukan pada induk dan edisi tersebut.');return $r[0];}
    public static function normalize($scope,$data,$lookup=null){$lookup=$lookup??[__CLASS__,'lookup'];$parent='';$out=$data;$codes=[];$gap=false;foreach(self::FIELDS as $i=>$field){$v=trim((string)($data[$field]??''));if($v===''){$gap=true;continue;}if($gap)return new WP_Error('hierarchy','Induk wilayah belum diisi: '.$field);$r=$lookup($scope,$parent,$i+1,$v);if(is_wp_error($r))return new WP_Error('match',$field.': '.$r->get_error_message());$out[$field]=$r['name'];$parent=$r['code'];$codes[$field]=$parent;}if(!$codes)return new WP_Error('missing','Minimal provinsi wajib diisi.');return ['data'=>$out,'codes'=>$codes];}
    private static function open_csv($path){$l=self::limits();if(!is_file($path)||filesize($path)>$l['bytes'])return new WP_Error('size','File melampaui batas mode aktif.');$f=fopen($path,'rb');if(!$f)return new WP_Error('file','CSV tidak dapat dibaca.');return $f;}
    private static function header($f){$h=fgetcsv($f,0,',','"','');if(!$h)return [];return array_map(fn($s)=>strtolower(trim(preg_replace('/^\xEF\xBB\xBF/','',(string)$s))),$h);}
    public static function parse_master($path,$scope,$source){$source=trim($source);if($source===''||strlen($source)>191)return new WP_Error('source','Nama/rujukan sumber wajib (maksimal 191 byte).');$f=self::open_csv($path);if(is_wp_error($f))return $f;try{if(self::header($f)!==self::HEADER)return new WP_Error('header','Header wajib: kode,kode_induk,jenis,nama.');$rows=[];$n=1;while(($v=fgetcsv($f,0,',','"',''))!==false){$n++;if($v===[null])continue;if(count($rows)>=self::limits()['rows']||count($v)!==4)return new WP_Error('row','Batas baris/kolom terlampaui pada baris '.$n);$r=self::row($scope,array_combine(self::HEADER,$v),$source);if(is_wp_error($r))return new WP_Error('row','Baris '.$n.': '.$r->get_error_message());if(isset($rows[$r['code']]))return new WP_Error('duplicate','Kode duplikat pada baris '.$n);$rows[$r['code']]=$r;}if(!$rows)return new WP_Error('empty','Tidak ada wilayah.');uasort($rows,fn($a,$b)=>$a['level']<=>$b['level']?:strcmp($a['code'],$b['code']));return $rows;}finally{fclose($f);}}
    public static function import($path,$scope,$source){global $wpdb;if(!self::ready())return new WP_Error('schema','Siapkan tabel master di menu terlebih dahulu.');$rows=self::parse_master($path,$scope,$source);if(is_wp_error($rows))return $rows;$t=self::table();$lock='sdp83_'.md5($t);if((string)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s, 2)',$lock))!=='1')return new WP_Error('busy','Impor lain berjalan.');try{foreach($rows as $r){$p=$r['parent'];if($p!==''){$parent=$rows[$p]??self::get($scope,$p);if(is_wp_error($parent))return $parent;if(!$parent||(int)$parent['level']!==$r['level']-1)return new WP_Error('parent','Induk tidak ditemukan: '.$p);}$existing=self::get($scope,$r['code']);if(is_wp_error($existing))return $existing;if($existing&&($existing['name']!==$r['name']||$existing['kind']!==$r['kind']||$existing['parent']!==$r['parent']))return new WP_Error('conflict','Kode '.$r['code'].' sudah berbeda pada edisi ini. Gunakan edisi baru setelah verifikasi.');}$count=0;foreach($rows as $r){$existing=self::get($scope,$r['code']);if(is_wp_error($existing))return $existing;if($existing)continue;if($wpdb->insert($t,$r)===false)return new WP_Error('database','Impor terhenti setelah '.$count.' rekaman baru. Ulangi file yang sama untuk melanjutkan.');$count++;}return ['inserted'=>$count,'unchanged'=>count($rows)-$count];}finally{$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));}}
    public static function safe_cell($v){return preg_match('//u',(string)$v)===1&&(preg_match('/^[\s\x{FEFF}]*[=+@-]/u',(string)$v)===0||preg_match('/^-?\d+(?:\.\d+)?$/D',(string)$v)===1);}
    public static function normalize_csv($path,$scope,$lookup=null){if($lookup===null&&!self::ready())return new WP_Error('schema','Siapkan master wilayah terlebih dahulu.');$f=self::open_csv($path);if(is_wp_error($f))return $f;$out=fopen('php://temp/maxmemory:262144','w+b');try{$h=self::header($f);if(count($h)>150||count($h)!==count(array_unique($h))||in_array('',$h,true)||!in_array('npsn',$h,true)||!in_array('provinsi',$h,true))return new WP_Error('header','Gunakan header unik npsn,provinsi dan kolom standar plugin.');foreach($h as $k)if(!isset(SDP_Directory::labels()[$k]))return new WP_Error('header','Kolom tidak dikenali: '.$k);fputcsv($out,$h,',','"','');$n=0;$line=1;while(($v=fgetcsv($f,0,',','"',''))!==false){$line++;if($v===[null])continue;if(++$n>self::limits()['rows']||count($v)!==count($h))return new WP_Error('row','Batas baris atau kolom tidak cocok pada baris '.$line);$d=array_combine($h,$v);if(!preg_match('/^[A-Z0-9]{8}$/Di',trim($d['npsn'])))return new WP_Error('npsn','NPSN tidak valid pada baris '.$line);$r=self::normalize($scope,$d,$lookup);if(is_wp_error($r))return new WP_Error('match','Baris '.$line.' ('.$d['npsn'].'): '.$r->get_error_message());foreach($r['data'] as $cell)if(!self::safe_cell($cell))return new WP_Error('formula','Sel berpotensi formula pada baris '.$line.'. Bersihkan sebelum ekspor.');if(fputcsv($out,array_values($r['data']),',','"','')===false||ftell($out)>self::limits()['bytes'])return new WP_Error('size','Hasil CSV melampaui batas.');}if(!$n)return new WP_Error('empty','Tidak ada sekolah.');rewind($out);return stream_get_contents($out);}finally{fclose($f);fclose($out);}}
    public static function menu(){add_submenu_page('sdp-directory','Master Wilayah','Master Wilayah','manage_options','sdp-region',[__CLASS__,'page']);}
    public static function page(){if(!current_user_can('manage_options'))return;echo '<div class="wrap"><h1>Master Wilayah Indonesia</h1><p>Master Kemendagri dan BPS terpisah berdasarkan edisi. Tidak ada data nasional bawaan atau sinkronisasi otomatis. Batas per file: '.esc_html(self::limits()['rows']).' baris. Gunakan CSV UTF-8 dengan kode sebagai teks.</p><form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="sdp83_region">';wp_nonce_field('sdp83_region');echo '<p>Status tabel: '.(self::ready()?'Siap':'Belum disiapkan').'</p><button class="button" name="task" value="install">Siapkan / periksa tabel</button><h2>Impor atau normalisasi</h2><p><label>Sistem <select name="system"><option value="kemendagri">Kemendagri</option><option value="bps">BPS</option></select></label> <label>Edisi <input name="edition" placeholder="2025" maxlength="32"></label></p><p><label>Rujukan sumber master <input name="source" maxlength="191"></label></p><p><label>CSV <input type="file" name="csv" accept=".csv"></label></p><p><label><input type="checkbox" name="authorized" value="1"> Saya berhak menggunakan data.</label></p><button class="button button-primary" name="task" value="import">Impor master wilayah</button> <button class="button" name="task" value="normalize">Normalisasi CSV sekolah dan unduh</button></form><p>Header master: <code>kode,kode_induk,jenis,nama</code>. Impor induk sebelum anak. Normalisasi sekolah tidak menulis profil; periksa hasil lalu gunakan Pengumpul Data. Nama ambigu/tidak dikenal menghentikan ekspor, tanpa tebakan. Gunakan edisi baru untuk perubahan wilayah.</p></div>';}
    public static function action(){if(!current_user_can('manage_options'))wp_die('Akses ditolak.');check_admin_referer('sdp83_region');$task=sanitize_key($_POST['task']??'');if($task==='install'){$r=self::install();if(is_wp_error($r))wp_die(esc_html($r->get_error_message()));wp_safe_redirect(admin_url('admin.php?page=sdp-region'));exit;}$f=$_FILES['csv']??[];if(!in_array($task,['import','normalize'],true)||empty($_POST['authorized'])||($f['error']??1)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']??'')||strtolower(pathinfo($f['name']??'',PATHINFO_EXTENSION))!=='csv')wp_die('File atau izin tidak valid.');$scope=self::scope(sanitize_text_field(wp_unslash($_POST['system']??'')),sanitize_text_field(wp_unslash($_POST['edition']??'')));if(is_wp_error($scope))wp_die(esc_html($scope->get_error_message()));$r=$task==='import'?self::import($f['tmp_name'],$scope,sanitize_text_field(wp_unslash($_POST['source']??''))):self::normalize_csv($f['tmp_name'],$scope);if(is_wp_error($r))wp_die(esc_html($r->get_error_message()));if($task==='normalize'){nocache_headers();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="sdp-wilayah-normal.csv"');echo $r;exit;}wp_die(esc_html('Impor selesai. Baru: '.$r['inserted'].'; tidak berubah: '.$r['unchanged']), 'Master Wilayah',['back_link'=>true,'response'=>200]);}
    public static function cli($args,$assoc){if(($assoc['authorized']??'')!=='1')WP_CLI::error('Gunakan --authorized=1 untuk dataset berizin.');$scope=self::scope($assoc['system']??'',$assoc['edition']??'');if(is_wp_error($scope))WP_CLI::error($scope->get_error_message());if(!self::ready()){$r=self::install();if(is_wp_error($r))WP_CLI::error($r->get_error_message());}$r=self::import($args[0]??'',$scope,sanitize_text_field($assoc['source']??''));if(is_wp_error($r))WP_CLI::error($r->get_error_message());WP_CLI::success(wp_json_encode($r));}
}
